	('ec', 'EC', 'Ecuador', '{es}', 'es', 'USD', 1.000000, '{VUELOS,PAQUETES,ALOJAMIENTOS,CARROS,UPGRADE,ESIM,UNIVERSAL}', '[{"tipo": "TARJETA", "marcas": ["VISA", "MASTERCARD", "AMEX", "DINERS"], "productos": ["PASAJE", "ADICIONAL"], "cuotasPermitidas": [1, 3, 6, 12]}]', '{}', '{"terminos": {"url": "/terminos", "version": "2026-10"}, "privacidad": {"url": "/privacidad", "version": "2026-10"}, "razonSocial": "RAM Alliance (proyecto académico, sin venta real)", "condicionesTransporte": {"url": "/condiciones-transporte", "version": "2026-10"}}', '[{"tipo": "CEDULA", "patron": "\\d{10}", "etiqueta": "Cédula (10 dígitos)"}, {"tipo": "RUC", "patron": "\\d{13}", "etiqueta": "RUC (13 dígitos)"}, {"tipo": "PASAPORTE", "patron": "[A-Za-z0-9]{5,20}", "etiqueta": "Pasaporte"}]', true, 1, '2026-10-06 21:02:35.806583+00');


