INSERT INTO public.ecom_plantillas_notificacion ("plantillaId", tipo, mercado, idioma, version, asunto, cuerpo, activa) VALUES
	('3c51634b-c7ba-42f2-91dd-bb643b022ae2', 'CONFIRMACION_COMPRA', NULL, 'es', 1, 'Confirmación de tu compra {{numeroOrden}}', 'Hola {{nombre}},

¡Tu compra fue confirmada!

Número de orden: {{numeroOrden}}
Código de reserva (PNR): {{pnr}}

Itinerario:
{{itinerario}}

Pasajeros y billetes electrónicos:
{{pasajeros}}

Total pagado: {{total}}

Puedes gestionar tu viaje con el número de orden o el código de reserva y el apellido del pasajero.

{{razonSocial}}
Términos y condiciones: {{urlTerminos}}', true),
	('1743b546-f97e-45a7-b6cc-3b8eda7dbaee', 'CONFIRMACION_COMPRA', NULL, 'en', 1, 'Your purchase {{numeroOrden}} is confirmed', 'Hello {{nombre}},

Your purchase is confirmed!

Order number: {{numeroOrden}}
Booking reference (PNR): {{pnr}}

Itinerary:
{{itinerario}}

Passengers and e-tickets:
{{pasajeros}}

Total paid: {{total}}

Manage your trip with the order number or booking reference and the passenger surname.

{{razonSocial}}
Términos y condiciones: {{urlTerminos}}', true),
	('99701aca-9a68-4f9f-8601-e7886d66e501', 'EMISION_FALLIDA', NULL, 'es', 1, 'No pudimos emitir tu orden {{numeroOrden}}', 'Hola,

No pudimos emitir los billetes de tu orden {{numeroOrden}}. La autorización de tu pago fue liberada: no se te cobró.

Puedes volver a intentar la compra o elegir otro vuelo.

{{razonSocial}}
Términos y condiciones: {{urlTerminos}}', true),
	('219c3a11-a1c5-4951-aa3e-33d26f7c36d4', 'VERIFICACION_CORREO', NULL, 'es', 1, 'Confirma tu correo', 'Hola {{nombre}},

Confirma tu correo con este enlace (vale 24 horas):
{{enlace}}

Si no creaste una cuenta, ignora este mensaje.

{{razonSocial}}
Términos y condiciones: {{urlTerminos}}', true),
	('a5a51429-62b9-4aec-b7f4-e9feff41b5a4', 'CUENTA_BLOQUEADA', NULL, 'es', 1, 'Bloqueamos temporalmente tu cuenta', 'Hola {{nombre}},

Detectamos varios intentos fallidos de inicio de sesión y bloqueamos tu cuenta por {{minutos}} minutos. Si no fuiste tú, recupera tu acceso.

{{razonSocial}}
Términos y condiciones: {{urlTerminos}}', true);


